      "production_summary_cn": "2026Q2 Caylloma锌含量为5,460吨（12.04百万磅），环比增加约4%；处理量增至141,337吨、锌品位升至4.26%，回收率保持在90.64%，公司称产量环比稳定并符合采矿顺序。",
