      "production_summary_cn": "2026Q1 Don David扣减前锌金属产量为1,143吨，同比增加64%。处理量同比增加31%，锌品位由1.68%升至1.91%，锌回收率由73.2%升至80.2%；承包商支持的掘进、设备可用率改善和采矿方法优化共同提升了产量。同期可付已产并售锌为962吨，同比增加56%；两者差异来自可付扣减、发运库存时点以及品位和回收率变化，不能相互替代。",
